-- 101 / CR-03. Statement evidence and allocations are nonfinancial; no tenant data on activation.
alter table public.journal_lines add constraint journal_lines_bank_company_identity unique(company_id,id);
create table public.bank_statements(
 id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id)on delete restrict,bank_id uuid not null,
 from_date date not null,through_date date not null,opening_minor bigint not null,closing_minor bigint not null,
 file_name text not null,file_sha256 text not null check(file_sha256~'^[a-f0-9]{64}$'),content_sha256 text not null,mapping jsonb not null,
 created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(company_id,id),unique(company_id,bank_id,file_sha256),unique(company_id,bank_id,content_sha256),
 foreign key(company_id,bank_id)references public.treasury_accounts(company_id,id)on delete restrict,check(through_date>=from_date)
);
create table public.bank_statement_lines(
 id uuid primary key default gen_random_uuid(),company_id uuid not null,statement_id uuid not null,row_number integer not null check(row_number>0),date date not null,amount_minor bigint not null check(amount_minor<>0),reference text not null,description text not null,raw jsonb not null,
 unique(company_id,id),unique(statement_id,row_number),foreign key(company_id,statement_id)references public.bank_statements(company_id,id)on delete restrict
);
create table public.bank_matches(
 id uuid primary key default gen_random_uuid(),company_id uuid not null,statement_id uuid not null,statement_line_id uuid not null,gl_line_id uuid not null,amount_minor bigint not null check(amount_minor>0),purpose text not null check(purpose in('MATCH','ADJUSTMENT')),reason text not null,actor uuid not null references auth.users(id),created_at timestamptz not null default now(),
 unique(company_id,id),foreign key(company_id,statement_id)references public.bank_statements(company_id,id)on delete restrict,foreign key(company_id,statement_line_id)references public.bank_statement_lines(company_id,id)on delete restrict,foreign key(company_id,gl_line_id)references public.journal_lines(company_id,id)on delete restrict
);
create table public.bank_unmatches(
 id uuid primary key default gen_random_uuid(),company_id uuid not null,match_id uuid not null unique,reason text not null,actor uuid not null references auth.users(id),created_at timestamptz not null default now(),foreign key(company_id,match_id)references public.bank_matches(company_id,id)on delete restrict
);
create table public.bank_reconciliation_events(
 event_no bigint generated always as identity unique,id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id),bank_id uuid not null,statement_id uuid,request_id uuid not null,action text not null,input_hash text not null,result jsonb not null,reason text not null,actor uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(company_id,request_id),foreign key(company_id,bank_id)references public.treasury_accounts(company_id,id),foreign key(company_id,statement_id)references public.bank_statements(company_id,id)
);
create table public.bank_adjustment_controls(
 company_id uuid not null references public.companies(id),kind text not null check(kind in('FEE','INTEREST')),account_id uuid not null,primary key(company_id,kind),foreign key(company_id,account_id)references public.accounts(company_id,id)
);
create table public.bank_adjustments(
 id uuid primary key,company_id uuid not null,statement_id uuid not null,statement_line_id uuid not null unique,kind text not null check(kind in('FEE','INTEREST')),amount_minor bigint not null,journal_id uuid not null,request_id uuid not null,reason text not null,actor uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(company_id,id),foreign key(company_id,statement_id)references public.bank_statements(company_id,id),foreign key(company_id,statement_line_id)references public.bank_statement_lines(company_id,id),foreign key(company_id,journal_id)references public.journal_entries(company_id,id)
);
-- Full bank reconciliation contains Payroll-derived cash information. No privilege escalation through a definer report.
create function public.can_reconcile_bank(cid uuid)returns boolean language sql stable security invoker set search_path='' as $$select auth.uid()is not null and(public.has_company_role(cid,'ACCOUNTING_ADMIN')or public.has_company_role(cid,'ACCOUNTANT'))and public.has_permission(cid,'payroll.manage')$$;
revoke all on function public.can_reconcile_bank(uuid)from public,anon,authenticated,service_role;grant execute on function public.can_reconcile_bank(uuid)to authenticated;
do $$declare t text;begin foreach t in array array['bank_statements','bank_statement_lines','bank_matches','bank_unmatches','bank_reconciliation_events','bank_adjustment_controls','bank_adjustments']loop
 execute format('alter table public.%I enable row level security',t);execute format('alter table public.%I force row level security',t);
 execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);execute format('grant select on public.%I to authenticated',t);
 execute format('create policy bank_read on public.%I for select to authenticated using(public.can_reconcile_bank(company_id))',t);
 if t<>'bank_adjustment_controls'then execute format('create trigger immutable_bank_evidence before update or delete on public.%I for each row execute function private.financial_evidence_immutable()',t);end if;
 end loop;end;$$;
create index bank_match_gl on public.bank_matches(company_id,gl_line_id);create index bank_match_statement on public.bank_matches(company_id,statement_id);create index bank_event_state on public.bank_reconciliation_events(company_id,statement_id,created_at,id);
create function private.bank_actor(cid uuid)returns uuid language plpgsql volatile set search_path=''as $$declare a uuid;begin a:=private.operational_finance_actor(cid,'accounting.post');if not public.can_reconcile_bank(cid)then raise exception 'Full bank reconciliation requires authorized Payroll ledger coverage'using errcode='42501';end if;return a;end;$$;
create function private.bank_final(cid uuid,sid uuid)returns boolean language sql stable set search_path=''as $$select coalesce((select action='FINALIZE'from public.bank_reconciliation_events where company_id=cid and statement_id=sid and action in('FINALIZE','REOPEN')order by event_no desc limit 1),false)$$;
create function private.bank_lock(cid uuid,bid uuid)returns void language sql volatile set search_path=''as $$select pg_advisory_xact_lock(hashtextextended(cid::text||bid::text,101))$$;
create function private.bank_remaining(cid uuid,lid uuid,is_gl boolean)returns numeric language sql stable set search_path=''as $$select coalesce(sum(m.amount_minor),0)from public.bank_matches m where m.company_id=cid and(case when is_gl then m.gl_line_id=lid else m.statement_line_id=lid end)and not exists(select 1 from public.bank_unmatches u where u.company_id=cid and u.match_id=m.id)$$;
create function private.bank_allocated_asof(cid uuid,lid uuid,cutoff date)returns numeric language sql stable set search_path=''as $$select coalesce(sum(m.amount_minor),0)from public.bank_matches m join public.bank_statements s on s.company_id=m.company_id and s.id=m.statement_id where m.company_id=cid and m.gl_line_id=lid and s.through_date<=cutoff and not exists(select 1 from public.bank_unmatches u where u.company_id=cid and u.match_id=m.id)$$;
-- Exact canonical reversal pairs with no matched cash effect are accounting cancellations, not outstanding bank movements.
create function private.bank_void_pair(cid uuid,jid uuid,cutoff date)returns boolean language sql stable set search_path=''as $$select exists(select 1 from public.journal_entries j join public.journal_entries o on o.company_id=j.company_id and(o.reversal_of_journal_entry_id=j.id or j.reversal_of_journal_entry_id=o.id)where j.company_id=cid and j.id=jid and j.posting_date<=cutoff and o.posting_date<=cutoff and not exists(select 1 from public.journal_lines l where l.company_id=cid and l.journal_entry_id in(j.id,o.id)and private.bank_allocated_asof(cid,l.id,cutoff)>0))$$;
create function private.bank_guard_final()returns trigger language plpgsql security definer set search_path=''as $$declare bid uuid;d date;begin
 if new.treasury_account_id is null then return new;end if;
 select id into bid from public.treasury_accounts where company_id=new.company_id and id=new.treasury_account_id and type='BANK';if bid is null then return new;end if;
 if not pg_try_advisory_xact_lock_shared(hashtextextended(new.company_id::text||bid::text,101))then raise exception 'Bank reconciliation transition in progress; retry unchanged request'using errcode='40001';end if;
 select posting_date into d from public.journal_entries where company_id=new.company_id and id=new.journal_entry_id;
 if exists(select 1 from public.bank_statements s where s.company_id=new.company_id and s.bank_id=bid and d<=s.through_date and private.bank_final(s.company_id,s.id))then raise exception 'Final bank reconciliation blocks backdated bank movement; audited reopen required'using errcode='23514';end if;return new;end;$$;
create trigger bank_final_movement_guard before insert on public.journal_lines for each row execute function private.bank_guard_final();
create function public.read_bank_reconciliation(cid uuid,sid uuid default null)returns jsonb language plpgsql stable security definer set search_path=''as $$
#variable_conflict use_variable
declare s public.bank_statements;lines jsonb;gl jsonb;matches jsonb;remaining numeric;outstanding numeric;balance numeric;begin
 if not public.can_reconcile_bank(cid)then raise exception 'Bank reconciliation access denied; full ledger authorization required'using errcode='42501';end if;
 if sid is null then return jsonb_build_object('banks',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'code',code,'name',name,'project_id',project_id)order by code),'[]')from public.treasury_accounts where company_id=cid and type='BANK'),'statements',(select coalesce(jsonb_agg(to_jsonb(x)||jsonb_build_object('opening_minor',x.opening_minor::text,'closing_minor',x.closing_minor::text,'final',private.bank_final(cid,x.id))order by through_date desc,id),'[]')from public.bank_statements x where company_id=cid),'controls',(select coalesce(jsonb_object_agg(kind,account_id),'{}')from public.bank_adjustment_controls where company_id=cid),'accounts',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'code',code,'name',name,'type',account_type)),'[]')from public.accounts where company_id=cid and status='ACTIVE'and account_type in('EXPENSE','REVENUE')and not requires_party));end if;
 select *into s from public.bank_statements where company_id=cid and id=sid;if not found then raise exception 'Statement not in Company'using errcode='42501';end if;
 select coalesce(jsonb_agg(to_jsonb(l)||jsonb_build_object('amount_minor',l.amount_minor::text,'remaining_minor',(abs(l.amount_minor::numeric)-private.bank_remaining(cid,l.id,false))::text)order by row_number),'[]')into lines from public.bank_statement_lines l where company_id=cid and statement_id=sid;
 select coalesce(jsonb_agg(jsonb_build_object('id',l.id,'journal_id',j.id,'date',j.posting_date,'reference',j.journal_reference,'business_reference',(select reference from public.commercial_documents where company_id=cid and journal_id=j.id limit 1),'description',j.description,'source',j.source_type,'reversal_of',j.reversal_of_journal_entry_id,'amount_minor',(l.debit_minor-l.credit_minor)::text,'remaining_minor',(abs(l.debit_minor::numeric-l.credit_minor)-private.bank_allocated_asof(cid,l.id,s.through_date))::text)order by j.posting_date,l.id),'[]')into gl from public.journal_lines l join public.journal_entries j on j.company_id=l.company_id and j.id=l.journal_entry_id where l.company_id=cid and l.treasury_account_id=s.bank_id and j.posting_date<=s.through_date and j.source_type<>'CERTIFIED_OPENING'and not private.bank_void_pair(cid,j.id,s.through_date);
 select coalesce(jsonb_agg(to_jsonb(m)||jsonb_build_object('amount_minor',m.amount_minor::text,'active',not exists(select 1 from public.bank_unmatches u where u.company_id=cid and u.match_id=m.id))order by created_at,id),'[]')into matches from public.bank_matches m where company_id=cid and statement_id=sid;
 select coalesce(sum((x->>'remaining_minor')::numeric),0)into remaining from jsonb_array_elements(lines)x;
 select coalesce(sum(sign((x->>'amount_minor')::numeric)*(x->>'remaining_minor')::numeric),0)into outstanding from jsonb_array_elements(gl)x;
 select coalesce(sum(l.debit_minor::numeric-l.credit_minor),0)into balance from public.journal_lines l join public.journal_entries j on j.company_id=l.company_id and j.id=l.journal_entry_id join public.treasury_accounts t on t.company_id=l.company_id and t.id=s.bank_id and t.gl_account_id=l.account_id where l.company_id=cid and j.posting_date<=s.through_date;
 return jsonb_build_object('statement',to_jsonb(s)||jsonb_build_object('opening_minor',s.opening_minor::text,'closing_minor',s.closing_minor::text),'final',private.bank_final(cid,sid),'lines',lines,'gl',gl,'matches',matches,'unmatched_statement_minor',remaining::text,'outstanding_net_minor',outstanding::text,'gl_balance_minor',balance::text,'adjusted_statement_minor',(s.closing_minor+outstanding)::text,'difference_minor',(balance-s.closing_minor-outstanding)::text,'cancelled_bank_journals',(select coalesce(jsonb_agg(distinct j.id),'[]')from public.journal_entries j join public.journal_lines l on l.company_id=j.company_id and l.journal_entry_id=j.id where j.company_id=cid and l.treasury_account_id=s.bank_id and private.bank_void_pair(cid,j.id,s.through_date)),'adjustments',(select coalesce(jsonb_agg(to_jsonb(a)||jsonb_build_object('amount_minor',a.amount_minor::text,'reversal_journal_id',(select id from public.journal_entries where company_id=cid and reversal_of_journal_entry_id=a.journal_id))),'[]')from public.bank_adjustments a where company_id=cid and statement_id=sid),'events',(select coalesce(jsonb_agg((to_jsonb(e)-'result')order by event_no),'[]')from public.bank_reconciliation_events e where company_id=cid and statement_id=sid));end;$$;
create function private.bank_adjustment_plan(cid uuid,sid uuid,lid uuid,kind text,reason text,tax_confirmed boolean)returns jsonb language plpgsql volatile set search_path=''as $$
#variable_conflict use_variable
declare s public.bank_statements;l public.bank_statement_lines;a public.accounts;t public.treasury_accounts;n bigint;begin
 select *into s from public.bank_statements where company_id=cid and id=sid;select *into l from public.bank_statement_lines where company_id=cid and statement_id=sid and id=lid;
 if l.id is null or kind not in('FEE','INTEREST')or tax_confirmed is distinct from true or length(btrim(reason))not between 5 and 1000 or private.bank_final(cid,sid)then raise exception 'Open statement, evidenced fee/interest and explicit no-tax-claim treatment required'using errcode='23514';end if;
 if private.bank_remaining(cid,lid,false)<>0 or exists(select 1 from public.bank_adjustments where company_id=cid and statement_line_id=lid)then raise exception 'Statement adjustment already matched or posted'using errcode='23505';end if;
 if(kind='FEE'and l.amount_minor>=0)or(kind='INTEREST'and l.amount_minor<=0)then raise exception 'Fee must be debit withdrawal; interest must be bank receipt'using errcode='23514';end if;
 select *into a from public.accounts where company_id=cid and id=(select account_id from public.bank_adjustment_controls where company_id=cid and bank_adjustment_controls.kind=bank_adjustment_plan.kind)and status='ACTIVE'and not requires_party;
 if a.id is null or a.account_type::text<>(case when kind='FEE'then'EXPENSE'else'REVENUE'end) then raise exception 'Configure appropriate active fee/interest control first'using errcode='23514';end if;
 select *into t from public.treasury_accounts where company_id=cid and id=s.bank_id;n:=abs(l.amount_minor);perform private.commercial_bank(cid,t.id,l.date,n,kind='FEE',t.project_id);
 return jsonb_build_object('date',l.date,'amount_minor',n::text,'lines',jsonb_build_array(private.commercial_line(t.gl_account_id,n,kind='FEE',null,t.project_id,t.id),private.commercial_line(a.id,n,kind='INTEREST',null,t.project_id)));end;$$;
create function public.preview_bank_adjustment(cid uuid,sid uuid,lid uuid,kind text,reason text,tax_confirmed boolean)returns jsonb language plpgsql volatile security definer set search_path=''as $$begin perform private.bank_actor(cid);return private.bank_adjustment_plan(cid,sid,lid,kind,reason,tax_confirmed);end;$$;
create function public.command_bank_reconciliation(cid uuid,request_id uuid,action text,input jsonb)returns jsonb language plpgsql volatile security definer set search_path=''as $$
#variable_conflict use_variable
declare actor uuid;bid uuid;sid uuid;s public.bank_statements;l public.bank_statement_lines;g public.journal_lines;j public.journal_entries;prior public.bank_reconciliation_events;h text;result jsonb;doc uuid:=gen_random_uuid();x jsonb;d date;n bigint;total numeric:=0;ln integer:=0;mid uuid;report jsonb;reason text;plan jsonb;jid uuid;req private.financial_command_requests;kind text;begin
 actor:=private.bank_actor(cid);if request_id is null or jsonb_typeof(input)is distinct from'object'or octet_length(input::text)>4000000 then raise exception 'Valid bounded command required'using errcode='22023';end if;
 -- Normalize typed working inputs before hashing; raw imported evidence remains byte-for-byte JSON.
 for kind in select key from jsonb_each(input)loop
  if kind in('amount_minor','opening_minor','closing_minor')and input->>kind~'^-?[0-9]{1,16}$'then input:=jsonb_set(input,array[kind],to_jsonb(((input->>kind)::bigint)::text));
  elsif kind in('reason','file_name')then input:=jsonb_set(input,array[kind],to_jsonb(btrim(input->>kind)));end if;
 end loop;
 perform private.serialize_operational_finance(cid,'OPERATIONS');h:=encode(extensions.digest(convert_to(jsonb_build_object('actor',actor,'action',action,'input',input)::text,'UTF8'),'sha256'),'hex');
 select *into prior from public.bank_reconciliation_events where company_id=cid and bank_reconciliation_events.request_id=command_bank_reconciliation.request_id;
 if found then if prior.input_hash<>h then raise exception 'Changed request intent'using errcode='23505';end if;return prior.result;end if;
 sid:=nullif(input->>'statement_id','')::uuid;reason:=btrim(coalesce(input->>'reason',''));if action='IMPORT'then bid:=(input->>'bank_id')::uuid;else select bank_id into bid from public.bank_statements where company_id=cid and id=sid;end if;
 if not exists(select 1 from public.treasury_accounts where company_id=cid and id=bid and type='BANK')then raise exception 'Same-Company actual Bank required'using errcode='42501';end if;perform private.bank_lock(cid,bid);
 if action='IMPORT'then
  if input->>'from_date'!~'^\d{4}-\d{2}-\d{2}$'or input->>'through_date'!~'^\d{4}-\d{2}-\d{2}$'or jsonb_typeof(input->'lines')is distinct from'array'or jsonb_array_length(input->'lines')not between 1 and 5000 or input->>'file_sha256'!~'^[a-f0-9]{64}$'or length(input->>'file_name')not between 1 and 255 or jsonb_typeof(input->'mapping')is distinct from'object' then raise exception 'Complete verified statement dates, mapping and file evidence required'using errcode='22023';end if;
  if input->>'opening_minor'!~'^-?[0-9]{1,16}$'or input->>'closing_minor'!~'^-?[0-9]{1,16}$'then raise exception 'Exact minor-unit balances required'using errcode='22023';end if;
  for x in select *from jsonb_array_elements(input->'lines')loop
   if x->>'date'!~'^\d{4}-\d{2}-\d{2}$'or x->>'amount_minor'!~'^-?[0-9]{1,16}$'or coalesce(length(x->>'reference'),1001)>500 or coalesce(length(x->>'description'),2001)>2000 or not(x?'raw')then raise exception 'Verified dates, exact signed amounts and original evidence required'using errcode='22023';end if;
   d:=(x->>'date')::date;n:=(x->>'amount_minor')::bigint;if n=0 or d<(input->>'from_date')::date or d>(input->>'through_date')::date then raise exception 'Statement line outside period or zero'using errcode='23514';end if;total:=total+n;
  end loop;
  if(input->>'through_date')::date<(input->>'from_date')::date or(input->>'opening_minor')::bigint+total<>(input->>'closing_minor')::bigint then raise exception 'Statement opening plus signed movements must equal closing'using errcode='23514';end if;
  -- Content fingerprint ignores filename, mapping/raw presentation and file row order but retains genuine repeated-line multiplicity.
  kind:=encode(extensions.digest(convert_to(jsonb_build_object('from',input->>'from_date','through',input->>'through_date','opening',(input->>'opening_minor')::bigint,'closing',(input->>'closing_minor')::bigint,'lines',(select jsonb_agg(jsonb_build_array(v->>'date',(v->>'amount_minor')::bigint,btrim(v->>'reference'),btrim(v->>'description'))order by v->>'date',(v->>'amount_minor')::bigint,v->>'reference',v->>'description')from jsonb_array_elements(input->'lines')v))::text,'UTF8'),'sha256'),'hex');
  select id into sid from public.bank_statements where company_id=cid and bank_id=bid and(file_sha256=input->>'file_sha256'or content_sha256=kind);
  if sid is not null then result:=jsonb_build_object('statement_id',sid,'duplicate',true);else
   if exists(select 1 from public.bank_statements where company_id=cid and bank_id=bid and from_date<=(input->>'through_date')::date and through_date>=(input->>'from_date')::date)then raise exception 'Overlapping statement period; use existing statement, do not duplicate evidence'using errcode='23505';end if;
   insert into public.bank_statements(id,company_id,bank_id,from_date,through_date,opening_minor,closing_minor,file_name,file_sha256,content_sha256,mapping,created_by)values(doc,cid,bid,(input->>'from_date')::date,(input->>'through_date')::date,(input->>'opening_minor')::bigint,(input->>'closing_minor')::bigint,input->>'file_name',input->>'file_sha256',kind,input->'mapping',actor);sid:=doc;
   for x in select *from jsonb_array_elements(input->'lines')loop ln:=ln+1;insert into public.bank_statement_lines(company_id,statement_id,row_number,date,amount_minor,reference,description,raw)values(cid,sid,ln,(x->>'date')::date,(x->>'amount_minor')::bigint,x->>'reference',x->>'description',x->'raw');end loop;result:=jsonb_build_object('statement_id',sid,'duplicate',false);end if;
 else
  if action<>'REOPEN'and private.bank_final(cid,sid)then raise exception 'Reconciliation finalized; audited reopen required'using errcode='23514';end if;
  select *into s from public.bank_statements where company_id=cid and id=sid;
  if action='MATCH'then
   select *into l from public.bank_statement_lines where company_id=cid and statement_id=sid and id=(input->>'line_id')::uuid;
   select *into g from public.journal_lines where company_id=cid and id=(input->>'gl_line_id')::uuid;select *into j from public.journal_entries where company_id=cid and id=g.journal_entry_id;
   if input->>'amount_minor'!~'^[0-9]{1,16}$'then raise exception 'Positive exact allocation required'using errcode='22023';end if;n:=(input->>'amount_minor')::bigint;
   if l.id is null or g.id is null or g.treasury_account_id is distinct from bid or not exists(select 1 from public.treasury_accounts where company_id=cid and id=bid and gl_account_id=g.account_id)or j.posting_date>s.through_date or j.source_type='CERTIFIED_OPENING'or private.bank_void_pair(cid,j.id,s.through_date)or sign(l.amount_minor)<>sign(g.debit_minor-g.credit_minor)then raise exception 'Same Bank, Company, sign and cutoff required'using errcode='23514';end if;
   if length(reason)not between 5 and 1000 or n<=0 or n>abs(l.amount_minor::numeric)-private.bank_remaining(cid,l.id,false)or n>abs(g.debit_minor::numeric-g.credit_minor)-private.bank_remaining(cid,g.id,true)then raise exception 'Allocation exceeds unmatched amount or evidence missing'using errcode='23514';end if;
   insert into public.bank_matches(id,company_id,statement_id,statement_line_id,gl_line_id,amount_minor,purpose,reason,actor)values(doc,cid,sid,l.id,g.id,n,case when exists(select 1 from public.bank_adjustments where company_id=cid and journal_id=g.journal_entry_id)then'ADJUSTMENT'else'MATCH'end,reason,actor);result:=jsonb_build_object('statement_id',sid,'match_id',doc);
  elsif action='UNMATCH'then
   if length(reason)not between 5 and 1000 or not exists(select 1 from public.bank_matches where company_id=cid and statement_id=sid and id=(input->>'match_id')::uuid)then raise exception 'Existing match and audited reason required'using errcode='23514';end if;
   insert into public.bank_unmatches(company_id,match_id,reason,actor)values(cid,(input->>'match_id')::uuid,reason,actor);result:=jsonb_build_object('statement_id',sid,'unmatched',true);
  elsif action='CONFIGURE'then
   if not public.has_company_role(cid,'ACCOUNTING_ADMIN')or not public.has_permission(cid,'account.manage')or length(reason)not between 5 and 1000 or input->>'kind'not in('FEE','INTEREST')then raise exception 'Accounting Admin and approved control mapping required'using errcode='42501';end if;
   if not exists(select 1 from public.accounts where company_id=cid and id=(input->>'account_id')::uuid and status='ACTIVE'and not requires_party and system_key is null and account_type::text=case when input->>'kind'='FEE'then'EXPENSE'else'REVENUE'end)then raise exception 'Appropriate active unreserved account required'using errcode='23514';end if;
